referenceFixTemplate:
abstract class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    abstract void speak();

    void sleep() {
        System.out.println(name + "睡着了，呼噜呼噜");
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：喵～");
    }
}

public class Main {
    public static void main(String[] args) {
        Cat c = new Cat("{name}");
        c.speak();
        c.sleep();
    }
}
